package ru.neverland.townymarket;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.locks.ReentrantLock;
import ru.neverland.core.*;import static ru.neverland.townymarket.MarketData.*;
/** Real atomic-file delay, legacy migration and rejected stale snapshots, without a mock writer. */
public final class MarketJournalSmoke{
 static int checks;static void check(boolean yes,String reason){if(!yes)throw new AssertionError(reason);checks++;}interface Work{void run()throws Exception;}static void rejects(Work work,String reason)throws Exception{try{work.run();}catch(Exception expected){checks++;return;}throw new AssertionError(reason);}static <T>T await(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(5,TimeUnit.SECONDS);}
 static ReentrantLock lock(Path file)throws Exception{var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(java.util.concurrent.ConcurrentMap<Path,ReentrantLock>)field.get(null);return locks.computeIfAbsent(file.toAbsolutePath().normalize(),p->new ReentrantLock());}
 static AuditRecord audit(Order o){return new AuditRecord(AuditRecord.id(MarketFunding.OWNER,o.id().toString(),o.auditStep()),o.phaseAt(),MarketFunding.OWNER,"MARKET_DEAL",o.auditOutcome(),o.id().toString(),AuditRecord.Party.system(),AuditRecord.Party.system(),AuditRecord.Party.system(),"STONE",o.amount(),MarketData.money(o.total()),"phase="+o.auditStep());}
 public static void main(String[] args)throws Exception{
  var folder=Files.createTempDirectory("market-ack-");var file=folder.resolve("market-data.yml");UUID lot=UUID.randomUUID(),seller=UUID.randomUUID(),buyer=UUID.randomUUID(),actor=UUID.randomUUID();long now=System.currentTimeMillis();var listing=new Listing(lot,seller,"AA==","Камень","stone",Scope.GLOBAL,false,100,64,now,ListingState.ACTIVE,"");var oldOrder=new Order(UUID.randomUUID(),lot,seller,buyer,actor,true,10,100,now,Phase.DEBIT_PENDING,now,"Old unknown debit",false);var legacy=new MarketRepository(file);legacy.load();legacy.put(listing);legacy.put(oldOrder);byte[] previous=Files.readAllBytes(file);
  var repo=new MarketJournal(file);repo.load();repo.audit(MarketJournalSmoke::audit);check(repo.order(oldOrder.id()).equals(oldOrder)&&repo.image().payments().isEmpty(),"legacy debit remains unknown without an invented bank request");check(Arrays.equals(previous,Files.readAllBytes(file)),"loading never rewrites schema1");
  var prepared=new Order(UUID.randomUUID(),lot,seller,buyer,actor,true,10,100,now,Phase.PREPARED,now,"Approved",false);await(repo.put(prepared));var ready=prepared.phase(Phase.DEBIT_READY,now,"Reserved");var terms=new MarketFunding.Terms(MarketFunding.debit(prepared.id()),buyer,actor,1000,"infrastructure","Exact purchase");var payment=new MarketFunding.Payment("TREASURY",terms);var before=repo.image();var gate=lock(file);gate.lock();CompletionStage<Order> write;
  try{write=repo.put(ready,payment,now);check(!write.toCompletableFuture().isDone()&&repo.busy()&&repo.image()==before,"new phase and protocol invisible until physical ACK");long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!gate.hasQueuedThreads()&&System.nanoTime()<end)Thread.sleep(1);check(gate.hasQueuedThreads()&&SuiteState.tryRun("market IO contention",()->{}),"slow disk never owns shared Suite state");rejects(()->await(repo.put(prepared)),"concurrent write blocked by acknowledged image");}finally{gate.unlock();}await(write);check(repo.image().payments().get(prepared.id()).equals(payment),"exact actor budget and amount acknowledged with phase");rejects(()->await(repo.put(prepared)),"stale PREPARED cannot overwrite reservation");rejects(()->await(repo.put(ready,new MarketFunding.Payment("DIRECT",null),now)),"new protocol cannot replace frozen Treasury intent");
  var pending=ready.phase(Phase.DEBIT_PENDING,now,"Waiting");await(repo.put(pending));var wait=pending.phase(Phase.DEBIT_PENDING,now+1000,"Bank busy");await(repo.put(wait));check(repo.image().audit().size()==3,"same phase polling never invents conflicting audit rows");await(repo.close());var restart=new MarketJournal(file);restart.load();restart.audit(MarketJournalSmoke::audit);check(restart.order(pending.id()).equals(wait)&&restart.image().payments().get(pending.id()).equals(payment),"pending order and exact protocol survive restart");check(restart.order(oldOrder.id()).phase()==Phase.DEBIT_PENDING&&!restart.image().payments().containsKey(oldOrder.id()),"legacy unresolved debit stays separate");
  var paid=pending.phase(Phase.PAID,now,"");await(restart.put(paid));var delivered=paid.phase(Phase.DELIVERED,now,"");await(restart.put(delivered));var credit=delivered.phase(Phase.CREDIT_PENDING,now,"");await(restart.put(credit));var retry=credit.phase(Phase.DELIVERED,now,"").phase(Phase.CREDIT_PENDING,now,"");rejects(()->await(restart.put(retry)),"skipping acknowledged manual decision is rejected");var manual=MarketPayments.resolve(credit,"credit-unpaid",now);await(restart.put(manual));var retryCredit=manual.phase(Phase.CREDIT_PENDING,now,"");await(restart.put(retryCredit));check(!retryCredit.auditStep().equals(credit.auditStep())&&retryCredit.phaseAt()>credit.phaseAt(),"retry retains operation and gains ordered audit identity");var completed=MarketPayments.resolve(retryCredit,"credit-paid",now);await(restart.put(completed));await(restart.put(completed.finish()));check(restart.demand().size()==1&&restart.order(completed.id()).finalized(),"completion demand and terminal state saved atomically once");rejects(()->await(restart.put(credit)),"terminal payment cannot be rewound");var rows=restart.image().audit();check(rows.stream().map(AuditRecord::id).distinct().count()==rows.size(),"every monetary transition has unique audit identity");check(rows.get(rows.size()-1).outcome().equals("COMPLETED"),"admin pending signals end with completed status");String first=rows.get(0).id();await(restart.auditAck(first));check(restart.image().audit().size()==rows.size()-1,"audit ACK removes only confirmed record");await(restart.close());var last=new MarketJournal(file);last.load();check(last.order(completed.id()).equals(completed.finish())&&last.demand().size()==1&&last.image().audit().size()==rows.size()-1,"restart retains finalized demand and remaining audit outbox");await(last.close());
  var broken=folder.resolve("broken.yml");Files.writeString(broken,"schema: 2\nlistings: {}\norders: {}\ndemand: {}\naudit-outbox: broken\n");var invalid=new MarketJournal(broken);rejects(invalid::load,"invalid journal must fail closed");await(invalid.close());check(Files.readString(broken).contains("audit-outbox: broken"),"shutdown preserves malformed file");rejects(()->new MarketJournal.Image(Map.of(lot,listing),Map.of(ready.id(),ready),List.of(),Map.of(),List.of()),"debit-ready requires durable payment marker");System.out.println("MarketJournalSmoke PASS "+checks+" checks");
 }
}
